  setPaused(value) {
    if (this.phase === 'ended' || this.phase === 'menu') return;
    if (value && this.phase === 'playing') {
      this.phase = 'paused';
      this.ui.setPaused(true);
      this.resetInput();
    } else if (!value && this.phase === 'paused') {
      this.phase = 'playing';
      this.ui.setPaused(false);
