  // ── Main loop ────────────────────────────────────────────────
  loop(now) {
    const dt = clamp((now - this.last) / 1000, 0, .05);
    this.last = now;
    this.clock += dt;
    if (this.screen === 'menu') {
      renderMenuBackdrop(this.el.menuCanvas, this.clock);
    } else if (this.screen === 'game') {
      if (this.phase === 'playing') this.update(dt);
      if (this.world) renderGame(this, dt);
      if (this.skillCheck.active) renderSkillCheck(this);
    } else if (this.screen === 'result') {
      renderResultBackdrop(this.el.resultCanvas, this.clock, this.resultOutcome === 'killer' ? 'killer' : 'survivor');
    }
    requestAnimationFrame(this.loop);
  }
}

