288:.player-card{position:absolute;left:calc(20px + var(--safe-left));bottom:calc(18px + var(--safe-bottom));display:flex;align-items:center;gap:10px;width:306px;padding:8px 13px 8px 8px;background:linear-gradient(100deg,rgba(8,14,16,.86),rgba(8,14,16,.48));border:1px solid rgba(215,225,216,.14);border-left:2px solid var(--amber);backdrop-filter:blur(8px)}
289:.player-portrait{position:relative;width:47px;height:47px;flex:0 0 auto;border-radius:50%;background:radial-gradient(circle at 50% 44%,#20302e,#0a1012 68%);border:1px solid rgba(223,231,220,.22);overflow:hidden}
290:.player-portrait span{position:absolute;inset:0;background:linear-gradient(145deg,transparent 48%,rgba(255,255,255,.08) 50%,transparent 52%)}
291:.player-portrait::before{content:'';position:absolute;left:50%;top:10px;width:15px;height:15px;border-radius:50%;background:var(--skin,#a88163);transform:translateX(-50%)}
292:.player-portrait::after{content:'';position:absolute;left:50%;bottom:-5px;width:33px;height:24px;border-radius:50% 50% 0 0;background:var(--shirt,#485e5a);transform:translateX(-50%)}
298:.health-pips{display:flex;gap:2px}
299:.health-pips i{display:block;width:22px;height:3px;background:rgba(215,225,216,.15);transform:skewX(-18deg)}
300:.health-pips i.on{background:#89b7ac;box-shadow:0 0 5px rgba(123,184,173,.3)}
301:.health-pips i.hurt{background:var(--blood)}
310:.ability-card{position:absolute;left:calc(340px + var(--safe-left));bottom:calc(18px + var(--safe-bottom));display:flex;align-items:center;gap:9px;width:180px;padding:9px 10px;background:rgba(8,14,16,.6);border:1px solid rgba(215,225,216,.13);opacity:0;transform:translateY(6px);transition:.25s;backdrop-filter:blur(6px)}
311:.ability-card.show{opacity:1;transform:none}
365:.touch-btn{width:62px;height:62px;border-radius:50%;border:1px solid rgba(215,225,216,.26);background:radial-gradient(circle at 42% 35%,rgba(255,255,255,.11),rgba(6,11,13,.7));color:var(--bone-dim);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;backdrop-filter:blur(4px);pointer-events:auto;touch-action:none;transition:.1s}
366:.touch-btn span{font-size:16px;line-height:1;font-weight:500}
367:.touch-btn b{font-size:6px;letter-spacing:.11em;font-weight:500;opacity:.7}
368:.touch-btn:active,.touch-btn.pressed{background:radial-gradient(circle at 42% 35%,rgba(213,162,74,.35),rgba(13,14,10,.86));border-color:rgba(213,162,74,.7);transform:scale(.96)}
505:  .player-card{left:50%;transform:translateX(-50%);bottom:calc(12px + var(--safe-bottom));width:200px;padding:5px 9px 5px 5px;border-left-width:1px;border-bottom:1px solid rgba(213,162,74,.5)}
506:  .player-portrait{width:32px;height:32px}
510:  .health-pips i{width:14px;height:2px}
513:  .ability-card{display:none}
541:  .player-card{width:188px}

.skill-check{position:absolute;left:50%;top:54%;transform:translate(-50%,-50%);display:none;flex-direction:column;align-items:center;pointer-events:none;filter:drop-shadow(0 10px 30px rgba(0,0,0,.8))}
.skill-check.show{display:flex;animation:skillIn .18s ease-out}
.skill-check canvas{width:176px;height:176px}
.skill-label{font-size:8px;letter-spacing:.38em;color:var(--amber);font-weight:600;margin-bottom:2px;text-shadow:0 0 12px rgba(213,162,74,.6)}
.skill-hint{margin-top:1px;font-size:7px;letter-spacing:.17em;color:#b7c0ba;display:flex;align-items:center;gap:5px;text-shadow:0 2px 6px #000}
.skill-hint kbd{color:var(--amber);border-color:rgba(213,162,74,.5);background:rgba(213,162,74,.1)}

.player-card{position:absolute;left:calc(20px + var(--safe-left));bottom:calc(18px + var(--safe-bottom));display:flex;align-items:center;gap:10px;width:306px;padding:8px 13px 8px 8px;background:linear-gradient(100deg,rgba(8,14,16,.86),rgba(8,14,16,.48));border:1px solid rgba(215,225,216,.14);border-left:2px solid var(--amber);backdrop-filter:blur(8px)}
.player-portrait{position:relative;width:47px;height:47px;flex:0 0 auto;border-radius:50%;background:radial-gradient(circle at 50% 44%,#20302e,#0a1012 68%);border:1px solid rgba(223,231,220,.22);overflow:hidden}
.player-portrait span{position:absolute;inset:0;background:linear-gradient(145deg,transparent 48%,rgba(255,255,255,.08) 50%,transparent 52%)}
.player-portrait::before{content:'';position:absolute;left:50%;top:10px;width:15px;height:15px;border-radius:50%;background:var(--skin,#a88163);transform:translateX(-50%)}
.player-portrait::after{content:'';position:absolute;left:50%;bottom:-5px;width:33px;height:24px;border-radius:50% 50% 0 0;background:var(--shirt,#485e5a);transform:translateX(-50%)}
.player-meta{flex:1;min-width:0}
.player-name{display:flex;align-items:baseline;gap:7px;white-space:nowrap}
.player-name b{font-size:11px;letter-spacing:.14em;color:var(--bone);font-weight:600}
.player-name em{font-size:6.5px;font-style:normal;letter-spacing:.16em;color:var(--amber);opacity:.9}
.vitals{display:flex;align-items:center;gap:8px;margin-top:3px}
.health-pips{display:flex;gap:2px}
.health-pips i{display:block;width:22px;height:3px;background:rgba(215,225,216,.15);transform:skewX(-18deg)}
.health-pips i.on{background:#89b7ac;box-shadow:0 0 5px rgba(123,184,173,.3)}
.health-pips i.hurt{background:var(--blood)}
.stamina-wrap{display:flex;align-items:center;gap:5px;flex:1;min-width:0}
.stamina-wrap span{font-size:5.5px;letter-spacing:.13em;color:#6e7b77}
.stamina{height:3px;flex:1;background:rgba(215,225,216,.12);overflow:hidden}
