angleBetween(a, b) {
  let d = (a - b + Math.PI) % TAU;
  if (d < 0) d += TAU;
  return Math.abs(d - Math.PI);
}

hitSurvivor(s) {
  if (!s || s.state !== 'alive') return;
  const k = this.killer;
  this.audio.hit();
  this.spawnBlood(s.x, s.y, s.injured ? 18 : 10);
  this.shake = Math.max(this.shake, s === this.player ? .95 : .45);
  if (!s.injured) {
    s.injured = true;
    s.health = 1;
    s.path = [];
    s.ai.think = 0;
    s.ai.state = 'flee';
